label("s",(15,7),W); label("p",(15,6),W); label("e",(15,5),W); label("e",(15,4),W); label("d",(15,3),W);
label("(B)",(14,9),NW);
draw((15,4)--(19,4),dashed); label("M",(19,4),E);
